<?php require '../includes/db.php';require '../includes/functions.php';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$n=trim($_POST['name']??'');$em=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$pw=$_POST['password']??'';if(!$n||!$em||strlen($pw)<8)$err='Enter valid details; password must be 8+ characters.';else{$h=password_hash($pw,PASSWORD_DEFAULT);$s=$conn->prepare('INSERT INTO users(name,email,password) VALUES(?,?,?)');try{$s->bind_param('sss',$n,$em,$h);$s->execute();header('Location: login.php?new=1');exit;}catch(Throwable $e){$err='Email is already registered.';}}}$page_title='Register';include '../includes/header.php';?><div class="formbox"><h1>Create Account</h1><?php if($err):?><p class="notice error"><?=e($err)?></p><?php endif;?><form method="post" data-validate><label>Name</label><input name="name" required><label>Email</label><input type="email" name="email" required><label>Password</label><input type="password" name="password" required><label>Confirm Password</label><input type="password" name="confirm_password" required><button class="btn">Register</button></form></div><?php include '../includes/footer.php';?>
